Before introducing our method, we set up the problem with more details. Specifically, we consider a graph $\cG = (\cV_1, \cV_2, \cE)$ with the node sets $\cV_1,\cV_2$ and the edge set $\cE$. Let $d_1=|\cV_1|$, $d_2=|\cV_2|$ and denote its weight matrix by $\bTheta \in \RR^{d_1\times d_2}$. In the undirected graph where $\cV_1 = \cV_2:=\cV$, $\bTheta$ is a square matrix and its element $\bTheta_{jk}$ is nonzero when there is an edge between node $j$ and node $k$, zero when there is no edge. 

In a bipartite graph where $\cV_1 \ne \cV_2$, elements of $\bTheta$ describe the existence of an edge between node j in $\cV_{1}$ and node $k$ in $\cV_{2}$. Without loss of generality, we focus on one of the node sets and denote it by $\cV$ with $|\cV|:=d$. We would like to select those nodes among $\cV$ whose degree exceeds a certain threshold $k_{\tau}$, \rev{based on the $n$ data samples $\bX_1, \cdots \bX_n \stackrel{i.i.d.}{\sim}  \bX  \in \RR^d $}. And the selection problem is equivalent to simultaneously testing $d$ hypotheses:
\begin{equation} \label{eq:problem_setup}
H_{0j}: \text{degree of node } j < k_{\tau} \text{  v.s.  }  H_{1j}:  \text{degree of node } j \ge k_{\tau},
\end{equation}
for $j \in [d]$.

Denote this generic estimator by $\tTheta$ (without causing confusion in notation), the maximum test statistic over a given subset $E$ of $\cV \times \cV$ will be
\begin{equation}\label{eq:T_E}
  T_{E}:= \max_{(j,k)\in E}\sqrt{n}\abr{\tTheta_{jk}  }  
\end{equation}

For each response variable $\bY^{(j)}, j \in [d_1]$, we compute the debiased Lasso estimator, denoted by $\tdTheta_{j}$ as 
\begin{align}\label{eq:dlasso}
\tdTheta_j = \hat \bTheta_j + \frac{1}{n}\, \Mb \bX^{\top}(\bY^{(j)} - \bX \hat  \bTheta_j), 
\text{ where  }\hat\bTheta_j= \arg\min_{\beta\in\RR^{d_2}}
\Big\{\frac{1}{2n}\|\bY^{(j)}-\bX\beta
\|^2_2+\lambda\|\beta\|_1\Big\}\, .  
\end{align}




Note the above $\Mb$ is defined as $\Mb = (m_1,\dots,m_{d_2})^{\top}$ where 
\begin{align}
\label{eq:optimization}
m_i = &\argmin_m  m^{\top} \hSigma m, \quad \text{s.t. }  \|\hSigma m - e_i \|_{\infty} \le \mu\,,
\end{align}

and here $\hSigma = (\bX^{\top} \bX)/n$. 


Then the debiased estimator of the parameter matrix, defined by $\tdTheta := (\tdTheta_{1}, \cdots, \tdTheta_{d_1})^\top$, will be used the input $\{\tTheta_e\}_{e \in \cV_1 \times \cV_2}$ of Algorithm \ref{algo:startrek}.

As the noise variance $\sigma_j$ is unknown, the scaled Lasso is used for its estimation \cite{javanmard2014confidence,sun2012scaled}, given by the following joint optimization problem,
\begin{equation}\label{eq:scaled_lasso}
    \{\hat\bTheta_j,\hat\sigma_j \} = \arg \min_{\beta \in \RR^{d_2}, \sigma > 0}\Big\{\frac{1}{2\sigma n}\|\bY^{(j)}-\bX\beta
    \|^2_2+ \frac{\sigma}{2} +
    \lambda\|\beta\|_1\Big\}.
\end{equation}

Regarding our testing problem, intuitively we can use the quantile of the Gaussian maxima of $ \cN(0,\hat \sigma_j^2 M\hSigma M^{\top})$ to approximate the quantile of maximum statistic $T_{E} =\underset{(j,k)\in E}{\max}\sqrt{n} |\tdTheta_{jk}|$ for some given subset $E$. Specifically, let $Z_j\mid \bX, \bY^{(j)}\sim  \cN(0,\hat \sigma_j^2 M\hSigma M^{\top})$ where $Z_j \in \RR^{d_2}$ and consider the subset $E \subset \{j\}\times \cV_2$, we approximate the quantile of $T_E$ by the following

\begin{equation}\label{eq:dlasso_chat}
T^{\cN}_{E} := \underset{(j,k)\in E}{\max} \; | Z_{jk} |,\quad \hat{c} (\alpha,E) = \inf \left\{ t\in \RR : \PPP_{Z} \left( T^{\cN}_{E} \le t  \right) \ge 1-\alpha    \right\}.
\end{equation}

Recall that $\cH_0 = \{j\in [d_1]: \norm{\bTheta_{j}}_0 < k_\tau\}$ with $d_0 = |\cH_0|$, we consider the following rows of $\bTheta$,
\begin{equation}\label{eq:strong_Y_set}
    \cB:=\{j\in \cH_{0}^{c}:\forall k \in \text{supp}(\bTheta_j),|\bTheta_{jk}|>c\sqrt{{\log d_2}/{n}}\},
\end{equation}
and define the proportion of such rows as $\rho = |\cB|/d_1$.
In the context of multitask regression, $\rho$ measures the proportion of hub response variables whose non-null parameter coefficients all exceed certain thresholds, thus characterizes the overall signal strength.

we consider the following one-step estimator $\{\dTheta_{e}\}_{e\in \cV \times \cV}$:
\begin{equation}
\label{eq:ggm_tdTheta}
\dTheta_{jk} := \hat{\bTheta}_{jk} - \frac{\hat{\bTheta}_{j}^{\top} \left( \hat{\bSigma} \hat{\bTheta}_k - \eb_k\right)}{\hat{\bTheta}_j^{\top} \hat{\bSigma}_j},
\quad
\tdTheta_{jk}:={\dTheta_{jk}}/{\sqrt{\dTheta_{jj}\dTheta_{kk}}}.
\end{equation}
where $\eb_k$ denotes the $k$th canonical basis in $\RR^d$.
then use its standardized version $\{\tdTheta_{e}\}_{e\in \cV \times \cV}$ as the input of Algorithm \ref{algo:startrek}.

The quantiles are approximated using the Gaussian multiplier bootstrap \cite{chernozhukov2013gaussian}: given the Gaussian multipliers $\xi_i \stackrel{\mathrm{i.i.d.}}{\sim} N(0,1)$, we compute
\begin{equation}\label{eq:ggm_chat}
\hat{c} (\alpha,E) = \inf \left\{ t\in \RR : \PPP_\xi \left( T^{\cB}_{E} \le t  \right) \ge 1-\alpha    \right\},
\end{equation}
where $T^{\cB}_{E} := \underset{(j,k)\in E}{\max} \; \frac{1}{\sqrt{n~ {\hat{\bTheta}_{jj}\hat{\bTheta}_{kk}}}}   \big|\sum_{i=1}^n  {\hat{\bTheta}^{\top}_j \left( \bX_i \bX_i^{\top} \hat{\bTheta}_k - \eb_k  \right)} \xi_i \big|$.

Now we consider the following set, 






\begin{equation}\label{eq:dep_term_set}

S = \{(j_1,j_2,k_1,k_2): j_1,j_2\in \cH_0, j_1\ne j_2,k_1 \ne k_2 , \bTheta_{j_1 j_2} = \bTheta_{j_1 k_1} = \bTheta_{j_2 k_2} = 0, \bTheta_{j_1 k_2} \ne 0, \bTheta_{j_2 k_1}\ne 0\}.
\end{equation}

Remark that in the above definition, $k_1$ can be the same as $j_2$ and $k_2$ can be the same as $j_1$.

\label{asp:tradeoff_fdp}
{Suppose that $\bTheta \in \cU(M,s, r_0)$ and the following conditions hold:}



\begin{enumerate}[(i)]



    \item Signal strength and scaling condition.
    \begin{eqnarray}\label{eq:cond1}
    \frac{\log d }{\rho}\rbr{
    \frac{(\log d)^{19/6}}{n^{1/6}} + \frac{ (\log d)^{11/6}}{\rho^{1/3} n^{1/6}} + 

    \frac{{s(\log d)^{3}}}{{n}^{1/2}}
    } = o(1).
    \end{eqnarray}

    \item Dependency and connectivity condition.


    \begin{eqnarray}\label{eq:cond2}
   \frac{\log d}{\rho d_0} + \frac{({\log d})^{2}|S|}{\rho d_0^2 p} = o(1).
    \end{eqnarray}
\end{enumerate}

We can then estimate the quantile of $T_E = \max_{e \in E} \sqrt{n}|\tilde\bTheta_e - \bTheta_e|$ by some Gaussian multiplier bootstrap statistic $T^{\cB}_{E}$, i.e.,
\begin{equation}
\label{eq:ggm_gen}
\hat{c} (\alpha,E) = \inf \left\{ t\in \RR : \PPP_\xi \left( T^{\cB}_{E} \le t  \right) \ge 1-\alpha    \right\},
\end{equation}

\label{asp:tradeoff_fdp_gen}
{Suppose that $\bTheta \in \cU(M,s, r_0)$ and the following scaling 
 condition holds:}
\begin{eqnarray} \nonumber 

    \frac{\log d }{\rho}\rbr{
    \frac{(\log d)^{19/6}}{n^{1/6}} + \frac{ (\log d)^{11/6}}{\rho^{1/3} n^{1/6}} + 
   \zeta_1 \log d + \frac{\zeta_2}{\rho}
    } + \zeta_2 d^4  +   \frac{\log d}{\rho d_0} + \frac{({\log d})^{2}|S|}{\rho d_0^2} = o(1),


    \end{eqnarray}
 where the definitions of $d_0$ and $\rho$ are the same as in Section \ref{sec:hub_selection}.
